head.script:
scwin.init = function() {
    scwin.param = scwin.$w.getParameter("paramData");
    //alert("[popup_wframe1 Screen] param data : " + JSON.stringify(scwin.param));
    var dataStr = scwin.$w.getPopupParam("id");
}
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.grd_memberList_onrowindexchange = function(row, oldRow) {
    var id = scwin.$w.parent().dlt_memberList.getCellData(row, "id");
    var name = scwin.$w.parent().dlt_memberList.getCellData(row, "name");
    ibx_idName1.setValue("Popup1 - [" + id + "] - " + name);
};
scwin.ibx_openPopup_onclick = function(e) {
    var paramData = {
        parentPopupId: scwin.$w.getPopupId(),
        rowData: WebSquare.wUnit.getObjById('dlt_memberList').getRowJSON(0)
    };
    var dataObj = {
        type: "json", // 데이터 타입. "xml","string","json","array" 
        data: paramData, // 전달 데이터 객체. 
        name: "paramData" // 변수명. popup에서 $w.getParameter( "rowObj" )로 깨내올 수 있다. 
    };
    var opts = {
        "id": "popup_wframe2",
        "type": "window",
        "width": "700px",
        "height": "250px",
        "top": 250,
        "left": 250,
        "popupName": "Popup2",
        "modal": false,
        "useIFrame": true,
        "dataObject": dataObj,
        "title": "focusTest",
        //			"alwaysOnTop" : false,
        "frameMode": "wframe"
    };
    $w.openPopup("popup_modal_false_WEFF-397_(WSQ-3743)_wframe2.xml", opts);
    //alert("[Open popup_wframe2]");
};
scwin.btn_trigger1_onclick = function(e) {
    var paramData = {
        parentPopupId: scwin.$w.getPopupId(),
        rowData: WebSquare.wUnit.getObjById('dlt_memberList').getRowJSON(0)
    };
    var dataObj = {
        type: "json", // 데이터 타입. "xml","string","json","array" 
        data: paramData, // 전달 데이터 객체. 
        name: "paramData" // 변수명. popup에서 $w.getParameter( "rowObj" )로 깨내올 수 있다. 
    };
    var opts = {
        "id": "popup_wframe3",
        "type": "window",
        "width": "700px",
        "height": "250px",
        "top": 250,
        "left": 250,
        "popupName": "Popup3",
        "modal": false,
        "useIFrame": true,
        "dataObject": dataObj,
        "title": "focusTest",
        //			"alwaysOnTop" : false,
        "frameMode": "wframe"
    };
    WebSquare.util.openPopup("popup_modal_false_WEFF-397_(WSQ-3743)_wframe2.xml", opts);
    //alert("[Open popup_wframe2]");		
};
scwin.setIdName = function(value) {
    ibx_idName1.setValue(value);
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.init();
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
